const storageKey='pdf.fjtd.dev.language';
let language='ja';
try{const saved=localStorage.getItem(storageKey);language=['ja','en'].includes(saved)?saved:(navigator.language.toLowerCase().startsWith('ja')?'ja':'en')}catch{language=navigator.language.toLowerCase().startsWith('ja')?'ja':'en'}
export function t(key,...values){const text=language==='en'?(english[key]??key):key;return text.replace(/\{(\d+)\}/g,(_,i)=>String(values[Number(i)]??''))}
export function getLanguage(){return language}
const textBindings=[],attributeBindings=[];
export function initLanguage(){
 const excluded='script,style,textarea,svg,#status,#count,#selection,#hint,#toolHint,#editorTitle,#contextTitle,#textLabel,#grid,#editList,#textTargets,#lockedName';
 const walker=document.createTreeWalker(document,NodeFilter.SHOW_TEXT);let node;
 while(node=walker.nextNode()){if(node.parentElement?.closest(excluded))continue;const key=node.textContent.trim();if(english[key])textBindings.push({node,key,before:node.textContent.match(/^\s*/)[0],after:node.textContent.match(/\s*$/)[0]})}
 for(const el of document.querySelectorAll('*')){if(el.closest('script,style,svg'))continue;for(const attr of ['aria-label','alt','placeholder','content']){const key=el.getAttribute(attr);if(english[key])attributeBindings.push({el,attr,key})}}
 const select=document.getElementById('language');select?.addEventListener('change',()=>setLanguage(select.value));
 applyLanguage();
 window.addEventListener('storage',event=>{if(event.key===storageKey&&['ja','en'].includes(event.newValue))setLanguage(event.newValue,false)});
}
function applyLanguage(){document.documentElement.lang=language;for(const b of textBindings)b.node.textContent=b.before+t(b.key)+b.after;for(const b of attributeBindings)b.el.setAttribute(b.attr,t(b.key));const select=document.getElementById('language');if(select){select.value=language;select.setAttribute('aria-label',language==='ja'?'表示言語':'Interface language')}}
export function setLanguage(next,persist=true){if(!['ja','en'].includes(next))return;language=next;if(persist)try{localStorage.setItem(storageKey,next)}catch{}applyLanguage();window.dispatchEvent(new CustomEvent('languagechange'))}
